import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionId = req.getHeader("X-Session-Id");
        if (sessionId == null || sessionId.isEmpty()) {
            resp.sendError(401, "Missing session");
            return;
        }

        // Validate session exists (simplified)
        if (!validateSession(sessionId)) {
            resp.sendError(403, "Invalid session");
            return;
        }

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Whitelist report types
        if (!reportType.matches("^(sales|inventory|payroll|audit)$")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String query = buildQuery(reportType, dateRange, department);
            logger.info("Executing report query for type: " + reportType);

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= cols; i++) {
                    row.put(meta.getColumnLabel(i), rs.getObject(i));
                }
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            logger.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildQuery(String reportType, String dateRange, String department) {
        String baseTable = reportType + "_reports";
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM ").append(baseTable);
        sb.append(" WHERE created_at >= NOW() - INTERVAL '").append(dateRange).append("'");
        if (department != null && !department.isEmpty()) {
            sb.append(" AND department = '").append(department).append("'");
        }
        sb.append(" ORDER BY created_at DESC LIMIT 500");
        return sb.toString();
    }

    private boolean validateSession(String sessionId) {
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            PreparedStatement ps = conn.prepareStatement(
                "SELECT 1 FROM sessions WHERE id = ? AND expires_at > NOW()");
            ps.setString(1, sessionId);
            return ps.executeQuery().next();
        } catch (SQLException e) {
            return false;
        }
    }
}
